<?php declare(strict_types=1);require_once __DIR__.'/includes/auth.php';$merchant=require_login();$pageTitle='API Keys';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$key='tg_'.bin2hex(random_bytes(30));$pdo->prepare('UPDATE merchants SET api_key=? WHERE id=?')->execute([$key,$merchant['id']]);$notice='API key rotated. Update your integrations now; the old key is no longer valid.';}$q=$pdo->prepare('SELECT api_key FROM merchants WHERE id=?');$q->execute([$merchant['id']]);$key=$q->fetchColumn();$counts=$pdo->prepare("SELECT substr(created_at,1,10) d,COUNT(*) n FROM orders WHERE merchant_id=? AND created_at>=? GROUP BY substr(created_at,1,10)");$counts->execute([$merchant['id'], date('Y-m-d', strtotime('-6 days'))]);$days=[];foreach($counts->fetchAll() as $r)$days[$r['d']]=(int)$r['n'];$max=max(1, ...(array_values($days) ?: [1]));require __DIR__.'/includes/dashboard-header.php';?>
<div class="page-title-row" style="margin-bottom:24px"><div><h1>API keys</h1><p>Authenticate server-to-server requests to the TG Gateways API.</p></div></div><?php if(!empty($notice)):?><div class="note panel"><?=h($notice)?></div><?php endif?><div class="dashboard-bottom-grid"><div class="card"><div class="card-title"><h3>Default API key</h3><span class="badge badge-success">Active</span></div><div class="field"><label>SECRET KEY · KEEP PRIVATE</label><div style="display:flex;gap:7px"><input id="api-key" value="<?=h($key)?>" type="password" readonly><button class="btn btn-secondary" data-toggle="#api-key">Reveal</button><button class="btn btn-secondary" onclick="navigator.clipboard.writeText(document.getElementById('api-key').value)">Copy</button></div></div><div class="callout callout-info" style="margin-top:15px">Never include your secret API key in a browser app, public repository, or client-side JavaScript. Rotate it immediately if exposed.</div><form method="post" style="margin-top:17px" onsubmit="return confirm('Rotate this key? Existing integrations will stop working.');"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><button class="btn btn-secondary">Roll API key</button></form></div><div class="card"><div class="card-title"><h3>API request activity</h3><span style="font-size:9px;color:#8692a5">Orders · 7 days</span></div><div class="bar-chart"><?php for($i=6;$i>=0;$i--):$d=date('Y-m-d',strtotime("-$i days"));$h=($days[$d]??0)?max(10,(int)(($days[$d]/$max)*100)):5;?><div class="bar" style="height:<?=$h?>%" title="<?=($days[$d]??0)?> orders"></div><?php endfor?></div><div class="bar-labels"><?php for($i=6;$i>=0;$i--):?><span><?=date('D',strtotime("-$i days"))?></span><?php endfor?></div></div></div><?php require __DIR__.'/includes/dashboard-footer.php';?>